package irvine.math.partition;

import java.util.Arrays;

import irvine.math.q.Q;

/**
 * Static utility methods for small integer arrays with descending values (the parts),
 * as they are generated by <code>IntegerPartition</code> or <code>DistinctPartsPartition</code>.
 * @author Georg Fischer
 */
public final class PartitionUtils {

  private PartitionUtils() { }

  /**
   * Determine whether a number is a part.
   * @param p partition
   * @param num number to be tested for membership
   * @return true for a part, false otherwise
   */
  public static boolean isPart(final int[] p, final int num) {
    final int len = p.length;
    if (len == 0) {
      return false;
    }
    if (num == 1) {
      return p[len - 1] == num;
    }
    for (int pi : p) {
      if (pi < num) {
        return false;
      }
      if (pi == num) {
        return true;
      }
    }
    return false;
  }

  /**
   * Get the least part.
   * @param p partition
   * @return minimal part
   */
  public static int min(final int[] p) {
    return p[p.length - 1];
  }

  /**
   * Get the greatest part.
   * @param p partition
   * @return maximal part
   */
  public static int max(final int[] p) {
    return p[0];
  }

  /**
   * Get the counts of the even and the odd parts, without multiplicity.
   * @param p partition
   * @return [evenCount, oddCount]
   */
  public static int[] evenOddCounts(final int[] p) {
    int evenCount = 0;
    int oddCount = 0;
    int old = 0;
    for (int n : p) {
      if (old != n) {
        old = n;
        if ((n & 1) == 0) {
          ++evenCount;
        } else {
          ++oddCount;
        }
        if (n == 1) {
          return new int[] {evenCount, oddCount};
        }
      } // else old == n: ignore
    }
    return new int[] {evenCount, oddCount};
  }

  /**
   * Get the counts of the even and the odd parts, with multiplicity.
   * @param p partition
   * @return [evenCount, oddCount]
   */
  public static int[] allEvenOddCounts(final int[] p) {
    int evenCount = 0;
    int oddCount = 0;
    for (int n : p) {
      if ((n & 1) == 0) {
        ++evenCount;
      } else {
        ++oddCount;
      }
    }
    return new int[] {evenCount, oddCount};
  }

  /**
   * Get the sums of the even and the odd parts, without multiplicity.
   * @param p partition
   * @return [evenCount, oddCount]
   */
  public static long[] evenOddSums(final int[] p) {
    long evenSum = 0;
    long oddSum = 0;
    int old = 0;
    for (int n : p) {
      if (old != n) {
        old = n;
        if ((n & 1) == 0) {
          evenSum += n;
        } else {
          oddSum += n;
        }
        if (n == 1) {
          return new long[] {evenSum, oddSum};
        }
      } // else old == n: ignore
    }
    return new long[] {evenSum, oddSum};
  }

  /**
   * Get the sums of the even and the odd parts, with multiplicity.
   * @param p partition
   * @return [evenCount, oddCount]
   */
  public static long[] allEvenOddSums(final int[] p) {
    long evenSum = 0;
    long oddSum = 0;
    for (int n : p) {
      if ((n & 1) == 0) {
        evenSum += n;
      } else {
        oddSum += n;
      }
    }
    return new long[] {evenSum, oddSum};
  }

  /**
   * Get the count of numbers that are congruent <code>res mod base</code>, without multiplicity.
   * @param p partition
   * @param base take the modulus to this base
   * @param res required residue
   * @return number of parts in <code>p</code> that fulfill the modulus condition
   */
  public static int modCount(final int[] p, final int base, final int res) {
    int count = 0;
    int old = 0;
    for (int n : p) {
      if (old != n) {
        old = n;
        if (n % base == res) {
          ++count;
        }
        if (n == 1) {
          return count;
        }
      } // else old == n: ignore
    }
    return count;
  }

  /**
   * Get the mean (average of parts).
   * @param p partition
   * @return sum(parts)/(number of parts), many a fraction
   */
  public static Q mean(final int[] p) {
    int sum = 0;
    for (int n : p) {
      sum += n;
    }
    return new Q(sum, p.length);
  }

  /**
   * Get the median, that is the average of the 2 middle parts if the length is even,
   * and the middle part if the length is odd.
   * @param p partition
   * @return a fraction
   */
  public static Q median(final int[] p) {
    final int len = p.length;
    if ((len & 1) == 1) {
      return new Q(p[len / 2]);
    }
    return new Q(p[len / 2 - 1] + p[len / 2], 2);
  }

  /**
   * Get the count of distinct parts.
   * @param p partition
   * @return number of distinct parts
   */
  public static int distinctCount(final int[] p) {
    int count = 0;
    int old = 0;
    for (int n : p) {
      if (old != n) {
        old = n;
        ++count;
        if (n == 1) {
          return count;
        }
      } // else old == n: ignore
    }
    return count;
  }

  /**
   * Get the multiplicity of a number.
   * @param p partition
   * @param num number to be counted
   * @return number of occurrences of <code>num</code>
   */
  public static int count(final int[] p, final int num) {
    int count = 0;
    int i = p.length;
    while (--i >= 0) {
      if (p[i] == num) {
        ++count;
      } else if (p[i] > num) {
        i = 0; // break loop
      }
    }
    return count;
  }

  /**
   * Get the minimum of the differences between adjacent parts.
   * @param p partition
   * @return <code>min(p[i] - p[i-1])</code>
   */
  public static int minDiff(final int[] p) {
    final int len = p.length;
    if (len <= 1) {
      return 0;
    }
    int i = 0;
    int old = p[i++];
    int diff = old - p[i++];
    while (i < len) {
      final int diff2 = old - p[i];
      if (diff2 < diff) {
        diff = diff2;
      }
      old = p[i++];
    }
    return diff;
  }

  /**
   * Get the maximum of the differences between adjacent parts.
   * @param p partition
   * @return <code>max(p[i] - p[i-1])</code>
   */
  public static int maxDiff(final int[] p) {
    final int len = p.length;
    if (len <= 1) {
      return 0;
    }
    int i = 0;
    int old = p[i++];
    int diff = old - p[i++];
    while (i < len) {
      final int diff2 = old - p[i];
      if (diff2 > diff) {
        diff = diff2;
      }
      old = p[i++];
    }
    return diff;
  }

  /**
   * Get the multiplicity of the least part.
   * @param p partition
   * @return count of min(p)
   */
  public static int minCount(final int[] p) {
    int count = 0;
    int i = p.length;
    if (i == 0) {
      return 0;
    }
    final int num = p[i - 1];
    while (--i >= 0) {
      if (p[i] == num) {
        ++count;
      } else if (p[i] > num) {
        i = 0; // break loop
      }
    }
    return count;
  }

  /**
   * Get the multiplicity of the largest part.
   * @param p partition
   * @return count of max(p)
   */
  public static int maxCount(final int[] p) {
    int count = 0;
    final int len = p.length;
    if (len == 0) {
      return 0;
    }
    final int num = p[0];
    for (int part : p) {
      if (part == num) {
        ++count;
      } else if (part < num) {
        return count;
      }
    }
    return count;
  }

  /**
   * Get the count of numbers that have multiplicity 1.
   * @param p partition
   * @return number of parts in <code>p</code> that occur only once
   */
  public static int singleCount(final int[] p) {
    final int len = p.length;
    if (len == 1) {
      return 1; // p0
    }
    int count = 0;
    int p0 = p[0];
    int p1 = p[1];
    if (p0 > p1) {
      ++count; // p0
    }
    if (len == 2) {
      return count * 2;
    }
    int p2 = 0;
    for (int i = 2; i < len; ++i) {
      p2 = p[i];
      if (p0 > p1 && p1 > p2) {
        ++count; // p1
      }
      p0 = p1;
      p1 = p2;
    }
    if (p0 > p1) {
      ++count; // p2
    }
    return count;
  }

  /**
   * Get the count of numbers that have multiplicity &gt; 1.
   * @param p partition
   * @return number of parts in <code>p</code> that occur more than once
   */
  public static int multiCount(final int[] p) {
    final int len = p.length;
    if (len == 1) {
      return 0;
    }
    int count = 0;
    int p0 = p[0];
    int p1 = p[1];
    if (len == 2) {
      return p0 == p1 ? 1 : 0;
    }
    int p2 = 0;
    for (int i = 2; i < len; ++i) {
      p2 = p[i];
      if (p0 == p1 && p1 > p2) {
        ++count; // p1
      }
      p0 = p1;
      p1 = p2;
    }
    if (p0 == p1) {
      ++count; // p2
    }
    return count;
  }

  /**
   * Print the results of all methods for the integer partitions of the given argument.
   * @param args number
   */
  public static void main(final String[] args) {
    final IntegerPartition ip = new IntegerPartition(Integer.parseInt(args[0]));
    int[] p;
    while ((p = ip.next()) != null) {
      System.out.println(Arrays.toString(p));
      System.out.println("  evenOddCounts:    " + Arrays.toString(evenOddCounts(p)));
      System.out.println("  allEvenOddCounts: " + Arrays.toString(allEvenOddCounts(p)));
      System.out.println("  evenOddSums:      " + Arrays.toString(evenOddSums(p)));
      System.out.println("  allEvenOddSums:   " + Arrays.toString(allEvenOddSums(p)));
      System.out.println("  min:              " + min(p));
      System.out.println("  max:              " + max(p));
      System.out.println("  count(p, 2):      " + count(p, 2));
      System.out.println("  minCount:         " + minCount(p));
      System.out.println("  maxCount:         " + maxCount(p));
      System.out.println("  minDiff:          " + minDiff(p));
      System.out.println("  maxDiff:          " + maxDiff(p));
      System.out.println("  singleCount:      " + singleCount(p));
      System.out.println("  multiCount:       " + multiCount(p));
      System.out.println("  isPart(p,2):      " + isPart(p, 2));
      System.out.println("  modCount(p,5,2):  " + modCount(p, 5, 2));
      System.out.println("  distinctCount:    " + distinctCount(p));
      System.out.println("  mean:             " + mean(p));
      System.out.println("  median:           " + median(p));
    }
  }
}
